<template><AppShell><view class="detail-crumb"><button class="text-button" @tap="go('home')">‹ 返回山河地图</button><button class="text-button" @tap="go('statistics')">收录说明</button></view><view class="registry-cover"><image src="/static/landscape.svg" mode="aspectFill"/><view><text class="eyebrow">山河人物 / PROVINCIAL ARCHIVE</text><text class="page-title">{{province?.name||'全国收录'}}</text><text class="muted">{{total}} 位收录人物 · 待独立复核</text></view></view><view class="registry-scope"><text>1919—1949年出生、牺牲或有重要贡献，符合一项即可。按资料包所记籍贯归类；不代表历史总人数。</text></view><view v-if="code==='320000'" class="fact-card"><text class="section-title">江苏名单如何计算</text><text class="reading-body">全国名单{{nationalCount}}人，详细档案新增{{detailAdded}}人，共{{total}}人。IP中的同一人物不重复计数。</text><text class="small">15份详细档案中，本页归属12人。周恩来按所记祖籍归浙江，江苏淮安为出生关联；宋振中出生地有不同记载，不由父母籍贯推导本人；钱振标已有江阴出生依据，明确籍贯来源本轮未取得可核正文，暂不并入籍贯统计。后两人仍计入全国总目录。</text></view><view class="filter-panel"><view class="search-field"><image src="/static/icons/search.png"/><input v-model="query" placeholder="在当前名单搜索姓名" confirm-type="search"/><button v-if="query" class="clear-button" @tap="query=''">×</button></view><picker :range="options" range-key="name" @change="select"><button class="outline">{{province?.name||'全部省份'}} ⌄</button></picker></view><view class="list-summary"><text>找到 {{items.length}} 位人物</text><text>资料名单 · 非审核通过名单</text></view><view v-if="items.length" class="registry-grid"><button v-for="(p,i) in items" :key="p.id" class="registry-card" @tap="p.readingId?go('person',{id:p.readingId}):go('registry',{id:p.id})"><text class="registry-number">{{String(i+1).padStart(2,'0')}}</text><view><text class="registry-name">{{p.name}}</text><text class="small">出生：{{p.birthText||'未载'}}</text><text class="small">籍贯／地域原文：{{p.originText||'待补充'}}</text><text v-if="p.regionEvidence" class="small">地域依据：{{p.regionEvidence.title}}</text></view><text class="small">{{p.memberships.join(' · ')}}{{p.readingId?' · 可深入阅读':''}}</text><text class="registry-arrow">↗</text></button></view><StatePanel v-else title="本批资料暂无对应条目" message="未收录不代表该地区没有英雄人物。可切换省份或清除关键词。"/><view class="next-actions"><button class="primary" @tap="go('people')">阅读典型人物档案 ↗</button><button class="outline" @tap="go('assistant')">向小迹提问</button></view></AppShell></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';import {onLoad,onShow} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StatePanel from '../../components/StatePanel.vue';import {provinces,list} from '../../lib/全国收录.js';import {go} from '../../lib/navigation.js'
const code=ref(''),query=ref(''),options=[{code:'',name:'全部省份'},...provinces,{code:'unknown',name:'地区待核'}],province=computed(()=>options.find(p=>p.code===code.value)),items=computed(()=>list(code.value,query.value)),total=computed(()=>list(code.value).length)
onLoad(o=>{code.value=options.some(p=>p.code===o.code)?o.code:''})
// #ifdef H5
function syncRegion(){if(!location.hash.includes('/pages/province/index'))return;const v=new URLSearchParams(location.hash.split('?')[1]||'').get('code')||'';if(options.some(p=>p.code===v)){code.value=v;query.value=''}}
onMounted(()=>window.addEventListener('hashchange',syncRegion));onBeforeUnmount(()=>window.removeEventListener('hashchange',syncRegion));onShow(syncRegion)
// #endif
const nationalCount=computed(()=>list(code.value).filter(p=>p.memberships.includes('全国名单')).length),detailAdded=computed(()=>list(code.value).filter(p=>!p.memberships.includes('全国名单')&&p.memberships.includes('详细档案')).length)
function select(e){code.value=options[Number(e.detail.value)]?.code||'';query.value=''}
</script>
